<script setup lang="ts">
import { computed, ref } from 'vue';
import LimitMeter from './LimitMeter.vue';
import { accounts, mixedAccounts } from './fixtures';
const props = withDefaults(defineProps<{ variant?: 'strip' | 'cards' | 'ledger'; mixed?: boolean; light?: boolean }>(), { variant: 'strip' });
const data = computed(() => props.mixed ? mixedAccounts : accounts);
const expanded = ref(false);
const settings = ref(false);
const amber = ref(70);
const red = ref(90);
const valid = computed(() => amber.value >= 1 && red.value <= 100 && amber.value < red.value);
const thresholds = computed(() => valid.value ? { amber: amber.value, red: red.value } : { amber: 70, red: 90 });
function leading(windows: typeof accounts[number]['windows']) { return [...windows].sort((a,b) => (b.state === 'fresh' ? b.used ?? -1 : -1) - (a.state === 'fresh' ? a.used ?? -1 : -1))[0]!; }
</script>
<template>
<main class="limits-lab" :class="[{ light }, variant]">
  <header class="lab-intro"><span>NOISY STUDIO / DESIGN LAB · 152</span><h1>Know when your crew needs a break.</h1><p>Agent provider limits · synthetic preview · no accounts connected</p></header>
  <div class="workspace">
    <div class="workspace-heading"><strong>Noisy Studio</strong><span>Dashboard <b>●</b> Connected · example</span></div>
    <section class="quota-panel" aria-label="Agent provider limits">
      <header class="panel-heading"><div><h2>Plan limits <span>ACCOUNT-WIDE</span></h2><p>Shared across conversations using the same account.</p></div><button @click="settings = !settings" :aria-expanded="settings">Thresholds {{ settings ? '−' : '+' }}</button></header>
      <div v-if="settings" class="thresholds"><label>Amber at <input v-model.number="amber" type="number" min="1" :max="red - 1" /> % used</label><label>Red at <input v-model.number="red" type="number" :min="amber + 1" max="100" /> % used</label><small>Preview only · defaults 70% / 90%</small><p v-if="!valid" role="alert">Choose 1–100%, with amber below red. Showing defaults until corrected.</p></div>
      <div class="accounts">
        <article v-for="account in data" :key="account.name" class="account">
          <header class="account-heading"><div class="provider-badge">{{ account.badge }}</div><div><h3>{{ account.name }}</h3><span>{{ account.account }}</span></div><span class="window-count">{{ account.windows.length }} {{ account.windows.length === 1 ? 'window' : 'windows' }}</span></header>
          <div class="windows"><LimitMeter v-for="window in (variant === 'strip' && !expanded ? [leading(account.windows)] : account.windows)" :key="window.name" :window="window" :amber="thresholds.amber" :red="thresholds.red" /></div>
          <p v-if="account.windows.some(window => window.state !== 'fresh')" class="summary-note">Some window data is unavailable or out of date</p>
          <p v-if="variant === 'strip' && !expanded" class="summary-note">{{ account.windows.length > 1 ? 'Highest current usage shown · other windows below' : 'This account reports a weekly window only' }}</p>
        </article>
      </div>
      <footer><span>{{ variant === 'strip' && !expanded ? 'Each account shows its most-used current window.' : 'Missing data is never shown as zero usage.' }}</span><button v-if="variant === 'strip'" @click="expanded = !expanded" :aria-expanded="expanded">{{ expanded ? 'Fewer details ↑' : 'All windows ↓' }}</button></footer>
    </section>
    <section class="context" aria-label="Dashboard placement example"><div><span class="eyebrow">YOUR CONVERSATIONS</span><h2>Ready when you are.</h2><p>Plan limits stay separate from individual agents and speech costs.</p></div><div class="conversation"><span class="avatar">A</span><div><strong>Atlas</strong><small>Release preparation</small></div><span>Claude Code</span></div><div class="conversation"><span class="avatar violet">N</span><div><strong>Nova</strong><small>Dashboard polish</small></div><span>Codex</span></div></section>
  </div>
  <aside class="design-caption"><strong>{{ variant === 'strip' ? 'A / Compact overview' : variant === 'cards' ? 'B / Account cards' : 'C / Window ledger' }}</strong><span>{{ variant === 'strip' ? 'Small by default. Expand only when you need the whole picture.' : variant === 'cards' ? 'All windows together, with room for model-specific limits.' : 'A scannable row for every window. More detail, more vertical space.' }}</span></aside>
</main>
</template>
